from pathlib import Path
import shutil
R=Path(__file__).resolve().parents[1];D=R/'dist'
css='''*{box-sizing:border-box}body{margin:0;background:#f6f8f2;color:#2b4434;font:14px/1.8 "Segoe UI","Microsoft YaHei",sans-serif}a{color:inherit}button,input,select{font:inherit}button{cursor:pointer}button:disabled{opacity:.45;cursor:default}.app{max-width:1060px;margin:auto;padding:28px}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #dce5d4;padding-bottom:25px}header a{text-decoration:none;font-size:12px}h1{font-size:30px;font-weight:450;margin:34px 0 10px}h2{font-weight:500;font-size:17px}.lead,.hint{color:#8b987f;font-size:12px}.workspace{display:grid;grid-template-columns:1fr 1.2fr;gap:25px;margin:30px 0}.panel{background:white;border:1px solid #e1e8d9;border-radius:10px;padding:25px}button,.file-label{display:inline-block;border:1px solid #d8e2cd;background:#edf2e7;color:#48663c;padding:10px 17px;border-radius:5px;text-decoration:none}button.primary{background:#315b43;color:white;border-color:#315b43}input:not([type=range]):not([type=checkbox]),select{width:100%;border:1px solid #d8e2cd;border-radius:5px;background:#fcfdf9;color:#3a5332;padding:11px;margin:8px 0 15px}input[type=file]{font-size:11px}label{font-size:12px;color:#809271}.now{display:flex;flex-direction:column;align-items:center;padding:25px 10px;min-height:250px;justify-content:center}.record-icon{height:120px;width:120px;background:repeating-radial-gradient(circle,#344b39 0 1px,#415b43 2px 3px);border-radius:50%;display:grid;place-items:center;box-shadow:0 10px 30px #30452c22}.record-icon:after{content:"";width:35px;height:35px;background:#c7dba3;border-radius:50%}.track-name{font-size:17px;margin:22px 0 10px;word-break:break-all;text-align:center}audio,video{width:100%;margin:15px 0}video{border-radius:8px;background:#1f3026;max-height:400px}.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.queue{padding:0;list-style:none}.queue button{text-align:left;display:flex;justify-content:space-between;width:100%;margin:6px 0;background:#f8faf4;border:1px solid #e7ecdf;font-size:12px;gap:12px}.queue button.active{background:#e4edd8}.queue small{white-space:nowrap;color:#94a285}.notice{border-left:2px solid #a8be8b;padding:12px 18px;background:#eef3e6;color:#7d9070;font-size:12px;margin:22px 0}.status{color:#678354;min-height:25px;font-size:12px;white-space:pre-wrap}a.download{display:inline-block;margin-top:15px;background:#315b43;color:white;border-radius:5px;padding:10px 18px;text-decoration:none}.split{display:grid;grid-template-columns:1fr 1fr;gap:25px}.code{white-space:pre-wrap;background:#263e30;color:#dae8cd;border-radius:6px;padding:24px;font:12px/1.8 Consolas,monospace;overflow:auto;max-height:520px}.route{border-top:1px solid #e4eadc;padding:20px 0}.route-fields{display:grid;grid-template-columns:1fr 1fr;gap:14px}.route h3{margin:0;font-size:15px}.route p{font-size:10px;color:#8b9d7d;margin:3px 0 13px}.login{max-width:480px;margin:75px auto}.locked{display:none}.admin-summary{display:flex;gap:18px;align-items:center;justify-content:space-between}.admin-summary h1{margin:25px 0}.actions{position:sticky;bottom:0;display:flex;gap:10px;background:#f6f8f2ee;padding:18px 0;backdrop-filter:blur(8px)}.checks{display:flex;gap:25px;flex-wrap:wrap;margin:16px 0}[hidden]{display:none!important}@media(max-width:700px){.app{padding:20px}.workspace,.split{grid-template-columns:1fr}.panel{padding:20px}h1{font-size:26px}.admin-summary{align-items:start}.route-fields{grid-template-columns:1fr}.actions{flex-wrap:wrap}}'''
(D/'assets'/'apps.css').write_text(css,encoding='utf-8')
def page(id,title,body,script):
 p=D/'apps'/id;p.mkdir(parents=True,exist_ok=True)
 (p/'index.html').write_text(f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · AIONE1</title><link rel="stylesheet" href="../../assets/apps.css"><script src="app.js" defer></script></head><body><main class="app"><header><a href="../../">AIONE1 / 姚毛毛</a><a href="../../tools/{id}/">产品介绍 ↗</a></header><h1>{title}</h1>{body}</main></body></html>''',encoding='utf-8')
 (p/'app.js').write_text(script,encoding='utf-8')
mediajs='''(()=>{const $=s=>document.querySelector(s);let tracks=[],current=-1;const audio=$('audio');function render(){const list=$('#queue');list.replaceChildren();const q=$('#filter').value.toLowerCase();tracks.forEach((t,i)=>{if(!t.name.toLowerCase().includes(q))return;const li=document.createElement('li'),b=document.createElement('button'),name=document.createElement('span'),kind=document.createElement('small');b.className=i===current?'active':'';name.textContent=t.name;kind.textContent=t.local?'本地文件':'网络音频';b.append(name,kind);b.onclick=()=>play(i);li.append(b);list.append(li)});$('#count').textContent=tracks.length+' 个音频'}function play(i){if(!tracks[i])return;current=i;audio.src=tracks[i].url;$('#track').textContent=tracks[i].name;audio.play().catch(()=>$('#status').textContent='请点击播放器播放按钮开始');render()}$('#files').onchange=e=>{for(const f of e.target.files){tracks.push({name:f.name,url:URL.createObjectURL(f),local:true})}render();if(current<0&&tracks.length)play(0);e.target.value=''};$('#add-url').onclick=()=>{try{const url=new URL($('#url').value);if(!['http:','https:'].includes(url.protocol))throw Error();if(location.protocol==='https:'&&url.protocol==='http:'){throw Error('HTTPS 页面请使用 HTTPS 音频地址')}tracks.push({name:decodeURIComponent(url.pathname.split('/').pop())||url.hostname,url:url.href,local:false});$('#url').value='';render();if(current<0)play(tracks.length-1);$('#status').textContent='已加入播放列表'}catch(e){$('#status').textContent=e.message.includes('HTTPS')?e.message:'请输入完整的 http 或 https 音频文件地址'}};$('#filter').oninput=render;$('#prev').onclick=()=>{if(tracks.length)play((current-1+tracks.length)%tracks.length)};$('#next').onclick=()=>{if(tracks.length)play((current+1)%tracks.length)};$('#rate').onchange=e=>audio.playbackRate=Number(e.target.value);audio.onloadedmetadata=()=>audio.playbackRate=Number($('#rate').value);audio.onended=()=>{if($('#repeat').checked&&tracks.length)play((current+1)%tracks.length)};audio.onerror=()=>$('#status').textContent='无法播放该文件。请检查格式、网络地址与访问权限；YouTube 网页链接不能作为音频直链播放。';$('#clear').onclick=()=>{audio.pause();audio.removeAttribute('src');audio.load();tracks.forEach(t=>{if(t.local)URL.revokeObjectURL(t.url)});tracks=[];current=-1;$('#track').textContent='选一段声音，开始聆听';render()};window.addEventListener('beforeunload',()=>tracks.forEach(t=>{if(t.local)URL.revokeObjectURL(t.url)}));render()})();'''
for id,title,lead in [('music','musicForYou · 网页轻听版','把本地音乐和音频直链，放进一个安静的播放器。'),('podcast','bokeForYou · 网页聆听版','导入本地节目或音频直链，用自己的节奏听一集播客。')]:
 body=f'''<p class="lead">{lead}由 Nginx 静态托管，无需 Node 服务。</p><div class="workspace"><section class="panel"><h2>添加音频</h2><label for="files">选择本地音乐或播客（支持多选）</label><input id="files" type="file" accept="audio/*,video/mp4,video/webm" multiple><label for="url">或添加音频文件直链</label><input id="url" type="url" placeholder="https://…/episode.mp3"><button id="add-url">加入列表</button><div class="status" id="status" role="status"></div><div class="notice">本地文件只在浏览器中播放，不会上传。列表只在本次页面会话保留。网页版提供本地播放与倍速；YouTube 搜索、下载、歌词等完整能力请使用桌面版。</div><a href="../../use/{id}/">完整桌面版与安装指引 ↗</a></section><section class="panel"><div class="now"><div class="record-icon" aria-hidden="true"></div><div class="track-name" id="track">选一段声音，开始聆听</div><audio controls preload="metadata"></audio><div class="controls"><button id="prev" aria-label="上一首">上一首</button><button id="next" aria-label="下一首">下一首</button><label>倍速 <select id="rate" aria-label="播放倍速"><option value="0.75">0.75×</option><option selected value="1">1×</option><option value="1.25">1.25×</option><option value="1.5">1.5×</option><option value="2">2×</option></select></label><label><input type="checkbox" id="repeat" checked> 连续播放</label></div></div><input id="filter" type="search" placeholder="搜索列表…" aria-label="搜索播放列表"><div class="controls"><small id="count"></small><button id="clear">清空列表</button></div><ul class="queue" id="queue"></ul></section></div>'''
 page(id,title,body,mediajs)

recorderjs='''(()=>{const $=s=>document.querySelector(s);let recorder,streams=[],chunks=[],url,context;const start=$('#start'),pause=$('#pause'),stop=$('#stop'),status=$('#status'),preview=$('video');function cleanup(){streams.forEach(s=>s.getTracks().forEach(t=>t.stop()));streams=[];if(context){context.close();context=null}start.disabled=false;pause.disabled=true;stop.disabled=true}if(!window.isSecureContext||!navigator.mediaDevices?.getDisplayMedia){start.disabled=true;status.textContent='屏幕录制需要 HTTPS 或本机 localhost。域名启用 HTTPS 后可直接使用；当前可以下载完整桌面版。'}start.onclick=async()=>{start.disabled=true;$('#download').hidden=true;chunks=[];try{const screen=await navigator.mediaDevices.getDisplayMedia({video:{frameRate:30},audio:$('#system').checked});streams.push(screen);if($('#mic').checked){const mic=await navigator.mediaDevices.getUserMedia({audio:true});streams.push(mic)}let stream=screen;const audioTracks=streams.flatMap(s=>s.getAudioTracks());if(audioTracks.length>1){context=new AudioContext();const dest=context.createMediaStreamDestination();for(const t of audioTracks){context.createMediaStreamSource(new MediaStream([t])).connect(dest)}stream=new MediaStream([...screen.getVideoTracks(),...dest.stream.getAudioTracks()])}else if(audioTracks.length===1){stream=new MediaStream([...screen.getVideoTracks(),audioTracks[0]])}preview.srcObject=screen;preview.controls=false;preview.muted=true;preview.play();const mime=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm','video/mp4'].find(v=>MediaRecorder.isTypeSupported(v));recorder=new MediaRecorder(stream,mime?{mimeType:mime}:{});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{if(url)URL.revokeObjectURL(url);const type=recorder.mimeType;url=URL.createObjectURL(new Blob(chunks,{type}));preview.srcObject=null;preview.src=url;preview.controls=true;preview.muted=false;const a=$('#download');a.href=url;a.download='AIONE1-recording-'+new Date().toISOString().replace(/[:.]/g,'-')+(type.includes('mp4')?'.mp4':'.webm');a.hidden=false;status.textContent='录制已完成，预览后点击下载保存。关闭页面前请保存文件。';cleanup()};screen.getVideoTracks()[0].onended=()=>{if(recorder?.state!=='inactive')recorder.stop()};recorder.start(1000);pause.disabled=false;stop.disabled=false;pause.textContent='暂停';status.textContent='正在录制。音频是否可用取决于浏览器与共享目标。'}catch(e){cleanup();status.textContent=e.name==='NotAllowedError'?'未授予共享或麦克风权限，录制未开始。':'无法开始录制：'+e.message}};pause.onclick=()=>{if(recorder.state==='recording'){recorder.pause();pause.textContent='继续';status.textContent='录制已暂停'}else if(recorder.state==='paused'){recorder.resume();pause.textContent='暂停';status.textContent='正在录制'}};stop.onclick=()=>{if(recorder&&recorder.state!=='inactive')recorder.stop()};window.addEventListener('beforeunload',()=>{streams.forEach(s=>s.getTracks().forEach(t=>t.stop()));if(url)URL.revokeObjectURL(url)})})();'''
page('video','videoForYou · 网页录屏版','''<p class="lead">直接在浏览器录制屏幕、窗口或标签页。文件只在本机浏览器生成。</p><div class="panel" style="margin-top:30px"><div class="checks"><label><input type="checkbox" id="system" checked> 请求共享目标的声音</label><label><input type="checkbox" id="mic"> 同时录制麦克风</label></div><div class="controls"><button id="start" class="primary">选择画面并开始录制</button><button id="pause" disabled>暂停</button><button id="stop" disabled>停止录制</button></div><p id="status" class="status" role="status">准备就绪</p><video playsinline></video><a id="download" class="download" hidden>下载录制文件 ↓</a></div><div class="notice">网页版提供基础录屏与声音混合，适用于支持屏幕共享的桌面浏览器。当前录制分片保存在浏览器内存，建议录制短片；滤镜、贴图和长时间录制请使用完整桌面版。系统声音取决于浏览器、操作系统与共享选项。</div><a href="../../use/video/">下载完整桌面版 ↗</a>''',recorderjs)
recorder_path=D/'apps'/'video'/'app.js'
text=recorder_path.read_text('utf-8')
text=text.replace("let recorder,streams=[],chunks=[],url,context;", "let recorder,streams=[],chunks=[],url,context;const mp4Mime=['video/mp4;codecs=avc1.42001E,mp4a.40.2','video/mp4;codecs=avc1.42E01E,mp4a.40.2','video/mp4'].find(v=>window.MediaRecorder&&MediaRecorder.isTypeSupported(v));")
text=text.replace("start.onclick=async()=>", "if(!mp4Mime){start.disabled=true;status.textContent='当前浏览器不支持直接录制 MP4。请使用较新版本的 Chrome / Edge，或下载完整桌面版。'}else if(!start.disabled){status.textContent='已就绪 · MP4 输出，开始后选择要共享的画面。'}start.onclick=async()=>")
text=text.replace("const mime=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm','video/mp4'].find(v=>MediaRecorder.isTypeSupported(v));", "const mime=mp4Mime;if(!mime)throw Error('当前浏览器无法录制 MP4');")
text=text.replace("+(type.includes('mp4')?'.mp4':'.webm')", "+'.mp4'")
recorder_path.write_text(text,encoding='utf-8')
p=D/'apps'/'video'/'index.html';text=p.read_text('utf-8').replace('直接在浏览器录制屏幕、窗口或标签页。文件只在本机浏览器生成。','直接在浏览器录制屏幕、窗口或标签页，导出 MP4。文件只在本机浏览器生成。').replace('下载录制文件 ↓','下载 MP4 录屏 ↓');p.write_text(text,encoding='utf-8')
